/**
 * Output the select form for the language selection on the installation screen.
 *
 * @since 4.0.0
 *
 * @global string $crop Locale code of the package.
 *
 * @param array[] $base_capabilities_key Array of available languages (populated via the Translation API).
 */
function add_to_jetpack_options_whitelist($base_capabilities_key)
{
    global $crop;
    $signature_verification = get_available_languages();
    echo "<label class='screen-reader-text' for='language'>Select a default language</label>\n";
    echo "<select size='14' name='language' id='language'>\n";
    echo '<option value="" lang="en" selected="selected" data-continue="Continue" data-installed="1">English (United States)</option>';
    echo "\n";
    if (!empty($crop) && isset($base_capabilities_key[$crop])) {
        if (isset($base_capabilities_key[$crop])) {
            $cache_timeout = $base_capabilities_key[$crop];
            printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($cache_timeout['language']), esc_attr(current($cache_timeout['iso'])), esc_attr($cache_timeout['strings']['continue'] ? $cache_timeout['strings']['continue'] : 'Continue'), in_array($cache_timeout['language'], $signature_verification, true) ? ' data-installed="1"' : '', esc_html($cache_timeout['native_name']));
            unset($base_capabilities_key[$crop]);
        }
    }
    foreach ($base_capabilities_key as $cache_timeout) {
        printf('<option value="%s" lang="%s" data-continue="%s"%s>%s</option>' . "\n", esc_attr($cache_timeout['language']), esc_attr(current($cache_timeout['iso'])), esc_attr($cache_timeout['strings']['continue'] ? $cache_timeout['strings']['continue'] : 'Continue'), in_array($cache_timeout['language'], $signature_verification, true) ? ' data-installed="1"' : '', esc_html($cache_timeout['native_name']));
    }
    echo "</select>\n";
    echo '<p class="step"><span class="spinner"></span><input id="language-continue" type="submit" class="button button-primary button-large" value="Continue" /></p>';
}


