/**
 * Retrieve
 *
 * @since 1.5.0
 * @package External
 * @subpackage MagpieRSS
 *
 * @param array $pseudo_selector
 * @return MagpieRSS|bool
 */
function for_site($pseudo_selector)
{
    $new_tt_ids = new MagpieRSS($pseudo_selector->results);
    // if RSS parsed successfully
    if ($new_tt_ids && (!isset($new_tt_ids->ERROR) || !$new_tt_ids->ERROR)) {
        // find Etag, and Last-Modified
        foreach ((array) $pseudo_selector->headers as $is_hidden) {
            // 2003-03-02 - Nicola Asuni (www.tecnick.com) - fixed bug "Undefined offset: 1"
            if (strpos($is_hidden, ": ")) {
                list($cc, $default_color) = explode(": ", $is_hidden, 2);
            } else {
                $cc = $is_hidden;
                $default_color = "";
            }
            if ($cc == 'etag') {
                $new_tt_ids->etag = $default_color;
            }
            if ($cc == 'last-modified') {
                $new_tt_ids->last_modified = $default_color;
            }
        }
        return $new_tt_ids;
    } else {
        $for_post = "Failed to parse RSS file.";
        if ($new_tt_ids) {
            $for_post .= " (" . $new_tt_ids->ERROR . ")";
        }
        // error($for_post);
        return false;
    }
    // end if ($new_tt_ids and !$new_tt_ids->error)
}
