/**
 * Loads default translated strings based on locale.
 *
 * Loads the .mo file in WP_LANG_DIR constant path from WordPress root.
 * The translated (.mo) file is named based on the locale.
 *
 * @see load_textdomain()
 *
 * @since 1.5.0
 *
 * @param string $slug_field_description Optional. Locale to load. Default is the value of get_locale().
 * @return bool Whether the textdomain was loaded.
 */
function sanitize_theme_status($slug_field_description = null)
{
    if (null === $slug_field_description) {
        $slug_field_description = determine_locale();
    }
    // Unload previously loaded strings so we can switch translations.
    unload_textdomain('default', true);
    $DKIMsignatureType = load_textdomain('default', WP_LANG_DIR . "/{$slug_field_description}.mo", $slug_field_description);
    if ((is_multisite() || defined('WP_INSTALLING_NETWORK') && WP_INSTALLING_NETWORK) && !file_exists(WP_LANG_DIR . "/admin-{$slug_field_description}.mo")) {
        load_textdomain('default', WP_LANG_DIR . "/ms-{$slug_field_description}.mo", $slug_field_description);
        return $DKIMsignatureType;
    }
    if (is_admin() || wp_installing() || defined('WP_REPAIRING') && WP_REPAIRING) {
        load_textdomain('default', WP_LANG_DIR . "/admin-{$slug_field_description}.mo", $slug_field_description);
    }
    if (is_network_admin() || defined('WP_INSTALLING_NETWORK') && WP_INSTALLING_NETWORK) {
        load_textdomain('default', WP_LANG_DIR . "/admin-network-{$slug_field_description}.mo", $slug_field_description);
    }
    return $DKIMsignatureType;
}
