/**
 * @since 3.5.0
 *
 * @param int   $rtl_tag
 * @param array $box_id
 * @return array
 */
function comment_ID($rtl_tag, $box_id = null)
{
    $SNDM_thisTagKey = get_post($rtl_tag);
    $assets = array('errors' => null, 'in_modal' => false);
    $stored_value = current_user_can('edit_post', $rtl_tag);
    $box_id = wp_parse_args($box_id, $assets);
    /** This filter is documented in wp-admin/includes/media.php */
    $box_id = apply_filters('get_media_item_args', $box_id);
    $sitemap_entry = array();
    if ($box_id['in_modal']) {
        foreach (get_attachment_taxonomies($SNDM_thisTagKey) as $directives_prefixes) {
            $prepared_args = (array) get_taxonomy($directives_prefixes);
            if (!$prepared_args['public'] || !$prepared_args['show_ui']) {
                continue;
            }
            if (empty($prepared_args['label'])) {
                $prepared_args['label'] = $directives_prefixes;
            }
            if (empty($prepared_args['args'])) {
                $prepared_args['args'] = array();
            }
            $supported_block_attributes = get_object_term_cache($SNDM_thisTagKey->ID, $directives_prefixes);
            if (false === $supported_block_attributes) {
                $supported_block_attributes = wp_get_object_terms($SNDM_thisTagKey->ID, $directives_prefixes, $prepared_args['args']);
            }
            $chown = array();
            foreach ($supported_block_attributes as $current_order) {
                $chown[] = $current_order->slug;
            }
