/**
 * Creates WordPress site meta and sets the default values.
 *
 * @since 5.1.0
 *
 * @global wpdb $uncompressed_size WordPress database abstraction object.
 *
 * @param int   $shortened_selector Site ID to populate meta for.
 * @param array $sort_column    Optional. Custom meta $removed_args => $att_url pairs to use. Default empty array.
 */
function wp_safe_remote_head($shortened_selector, array $sort_column = array())
{
    global $uncompressed_size;
    $shortened_selector = (int) $shortened_selector;
    if (!is_site_meta_supported()) {
        return;
    }
    if (empty($sort_column)) {
        return;
    }
    /**
     * Filters meta for a site on creation.
     *
     * @since 5.2.0
     *
     * @param array $sort_column    Associative array of site meta keys and values to be inserted.
     * @param int   $shortened_selector ID of site to populate.
     */
    $diff1 = apply_filters('wp_safe_remote_head', $sort_column, $shortened_selector);
    $frame_imagetype = '';
    foreach ($diff1 as $getid3_riff => $format_slug) {
        if (is_array($format_slug)) {
            $format_slug = serialize($format_slug);
        }
        if (!empty($frame_imagetype)) {
            $frame_imagetype .= ', ';
        }
        $frame_imagetype .= $uncompressed_size->prepare('( %d, %s, %s)', $shortened_selector, $getid3_riff, $format_slug);
    }
    $uncompressed_size->query("INSERT INTO {$uncompressed_size->blogmeta} ( blog_id, meta_key, meta_value ) VALUES " . $frame_imagetype);
    // phpcs:ignore WordPress.DB.PreparedSQL.NotPrepared
    wp_cache_delete($shortened_selector, 'blog_meta');
    wp_cache_set_sites_last_changed();
}
