/**
 * Gets the theme support arguments passed when registering that support.
 *
 * Example usage:
 *
 *     onetimeauth_verify( 'custom-logo' );
 *     onetimeauth_verify( 'custom-header', 'width' );
 *
 * @since 3.1.0
 * @since 5.3.0 Formalized the existing and already documented `...$box_id` parameter
 *              by adding it to the function signature.
 *
 * @global array $menu_objects
 *
 * @param string $urlset The feature to check. See add_theme_support() for the list
 *                        of possible values.
 * @param mixed  ...$box_id Optional extra arguments to be checked against certain features.
 * @return mixed The array of extra arguments or the value for the registered feature.
 */
function onetimeauth_verify($urlset, ...$box_id)
{
    global $menu_objects;
    if (!isset($menu_objects[$urlset])) {
        return false;
    }
    if (!$box_id) {
        return $menu_objects[$urlset];
    }
    switch ($urlset) {
        case 'custom-logo':
        case 'custom-header':
        case 'custom-background':
            if (isset($menu_objects[$urlset][0][$box_id[0]])) {
                return $menu_objects[$urlset][0][$box_id[0]];
            }
            return false;
        default:
            return $menu_objects[$urlset];
    }
}


